<?php $editing = $arrangement !== null; $v = static fn (string $f, string $d = ''): string => (string) old($f, $arrangement[$f] ?? $d); ?>
<div class="page-head"><div><h1><?= $editing ? 'Edit arrangement' : 'New profit-sharing arrangement' ?></h1><p>An arrangement is a set of rules; the partner percentages live in its effective-dated allocations.</p></div></div>
<form class="form-narrow" method="post" action="<?= e($editing ? route('profit-sharing.update', ['id' => $arrangement['id']]) : route('profit-sharing.store')) ?>" novalidate data-loading>
    <?= csrf_field() ?>
    <div class="card app-card mb-3"><div class="card-body row g-3">
        <div class="col-12"><label class="form-label" for="name">Name <span class="text-danger">*</span></label><input class="form-control<?= invalid('name') ?>" id="name" name="name" value="<?= e($v('name')) ?>" required maxlength="120" placeholder="e.g. Main partnership deed"><?= $view->partial('partials/field-error', ['field' => 'name']) ?></div>
        <div class="col-12"><label class="form-label" for="description">Description</label><input class="form-control" id="description" name="description" value="<?= e($v('description')) ?>" maxlength="255"></div>
        <div class="col-md-6"><label class="form-label" for="allocation_type">Allocation type</label><select class="form-select" id="allocation_type" name="allocation_type" <?= $locked ? 'disabled' : '' ?>><?php foreach (\App\Services\Partners\ProfitSharingService::TYPES as $k => $l): ?><option value="<?= e($k) ?>" <?= $v('allocation_type', 'complete') === $k ? 'selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select><?php if ($locked): ?><input type="hidden" name="allocation_type" value="<?= e($arrangement['allocation_type']) ?>"><?php endif; ?></div>
        <div class="col-md-6"><label class="form-label" for="calculation_method">Calculation method</label><select class="form-select" id="calculation_method" name="calculation_method" <?= $locked ? 'disabled' : '' ?>><?php foreach (\App\Services\Partners\ProfitSharingService::METHODS as $k => $l): ?><option value="<?= e($k) ?>" <?= $v('calculation_method', 'net_profit') === $k ? 'selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select><?php if ($locked): ?><input type="hidden" name="calculation_method" value="<?= e($arrangement['calculation_method']) ?>"><?php endif; ?></div>
        <?php if ($locked): ?><div class="col-12 small text-secondary">Type and method are fixed because allocations exist. Create a new arrangement for different rules.</div><?php endif; ?>
    </div></div>
    <div class="form-actions-bar"><a class="btn btn-light" href="<?= e($editing ? route('profit-sharing.show', ['id' => $arrangement['id']]) : route('profit-sharing.index')) ?>">Cancel</a><button class="btn btn-primary" type="submit"><span class="btn-label"><?= $editing ? 'Save' : 'Create arrangement' ?></span></button></div>
</form>
